											discount_amount = ifnull(input.Discount_Amount,0.0);
											// =================================================
											// 7. CALCULATE AMOUNT DUE
											// =================================================
											input.Amount_Due = input.Total_Amount + tax_amount - discount_amount;
											// =================================================
											// 8. AMOUNT PAID
											// Uses current Amount Paid
											// =================================================
											amount_paid = ifnull(input.Amount_Paid,0.0);
											// =================================================
											// 9. CALCULATE BALANCE DUE
											// =================================================
											input.Balance_Due = input.Amount_Due - amount_paid;
										}

if(input.Site_Location != null)
										{
											input.Display_Name_Site_Location = input.Site_Location.Site_Location_Name;
										}
										else
										{
											input.Display_Name_Site = "";
										}
										mat = ifnull(input.Materials_Produced,"");
										site_from = "";
										if(input.Site != null)
										{
											site_from = ifnull(input.Site.Display_Name_Asset_Name,"");
										}
										loc_from = ifnull(input.Display_Name_Site_Location,"");
										input.Batch_Details = "Materials Produced is " + mat + " at " + site_from + " - " + loc_from;

// =====================================================
										// ON DELETE FINALIZE
										// =====================================================
										// =====================================================
										// SECTION 1: VARIABLES
										// =====================================================
										case_no = ifnull(input.Case_Number,"").trim();
										voucherType = ifnull(input.Display_Name_Voucher_Type,"").trim();
										// =====================================================
										// SECTION 2: UPDATE SUPERVISOR VOUCHER SUMMARY
										// =====================================================
										if(input.ID != null && voucherType == "Supervisor Voucher")
										{
											thisapp.voucher.update_supervisor_voucher_summary(input.ID);
										}
										// =====================================================
										// SECTION 3: UPDATE TRANSFER REGISTER COUNT
										// =====================================================
										if(case_no != "")
										{
											employee_management.updateVoucherTransferRegisterCount(case_no);
										}
										// =====================================================
										// SECTION 4: RECALCULATE VOUCHER MATERIAL COST
										// =====================================================
										if(input.ID != null)
										{
											thisapp.recalculateVoucherMaterialsCost(input.ID);
											thisapp.updateVoucherQuantityCreated(input.ID);
										}
